import json

def solve(data):
    def edit_distance(s1, s2):
        if not s1:
            return len(s2)
        if not s2:
            return len(s1)

        if s1[-1] == s2[-1]:
            return edit_distance(s1[:-1], s2[:-1])
        else:
            return 1 + min(edit_distance(s1[:-1], s2), edit_distance(s1, s2[:-1]), edit_distance(s1[:-1], s2[:-1]))

    return edit_distance(data['a'], data['b'])
